const $=id=>document.getElementById(id);
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const on=(el,ev,fn)=>el&&el.addEventListener(ev,fn);
const setText=(id,t)=>{const el=$(id);if(el)el.textContent=t};
const [examGrid,examSearch,categoryFilter,levelFilter,examCount,emptyState,dialog,dialogContent,toast]=
  ["examGrid","examSearch","categoryFilter","levelFilter","examCount","emptyState","examDialog","dialogContent","toast"].map($);

/* ---------- Exams ---------- */
const PAGE_SIZE=12;let visibleCount=PAGE_SIZE;
const moreBtn=document.createElement("button");
moreBtn.textContent="Explore more exams";
moreBtn.style.cssText="display:none;margin:24px auto;padding:14px 28px;border-radius:14px;border:1px solid #3b82f6;background:transparent;color:#60a5fa;font-size:16px;font-weight:600;cursor:pointer";
examGrid.insertAdjacentElement("afterend",moreBtn);

function renderExams(reset=true){
  if(reset)visibleCount=PAGE_SIZE;
  const q=examSearch.value.trim().toLowerCase(),cat=categoryFilter.value,lvl=levelFilter.value;
  const list=exams.filter(e=>(!q||[e.name,e.short,e.category,e.description,e.purpose].join(" ").toLowerCase().includes(q))&&(cat==="all"||e.category===cat)&&(lvl==="all"||e.level===lvl));
  examGrid.innerHTML=list.slice(0,visibleCount).map(e=>`
    <article class="exam-card">
      <div class="exam-top"><span class="exam-icon">${e.icon}</span><span class="tag">${esc(e.category)}</span></div>
      <h3>${esc(e.short)}</h3><p>${esc(e.description)}</p>
      <div class="exam-meta">${esc(e.level)}</div>
      <button class="details-button" data-exam="${esc(e.id)}">Explore details →</button>
    </article>`).join("");
  examCount.textContent=`${list.length} of ${exams.length} exams`;
  emptyState.hidden=list.length>0;
  moreBtn.style.display=visibleCount<list.length?"block":"none";
}
const list$=(a,t="ul")=>`<${t} class="detail-list">${a.map(x=>`<li>${esc(x)}</li>`).join("")}</${t}>`;
const block=(h,b)=>`<div class="detail-block"><h4>${h}</h4>${b}</div>`;
function openExam(id){
  const e=exams.find(x=>x.id===id);if(!e)return;
  dialogContent.innerHTML=`
    <div class="dialog-category">${esc(e.category)} · ${esc(e.level)}</div>
    <h2 class="dialog-title">${esc(e.name)}</h2>
    <p class="dialog-description">${esc(e.description)}</p>
    ${block("Purpose",`<p>${esc(e.purpose)}</p>`)}
    ${block("Eligibility overview",`<p>${esc(e.eligibility)}</p>`)}
    ${block("Subjects / assessment areas",list$(e.subjects))}
    ${block("Typical selection stages",list$(e.stages,"ol"))}
    ${block("What to do next",`<p>${esc(e.next)}</p><a class="button primary" href="${esc(e.official)}" target="_blank" rel="noopener">Official website ↗</a>`)}
    <p class="dialog-description">Rules can change. This summary is a starting guide, not an official notification.</p>`;
  dialog.showModal();
}
function showToast(msg){
  toast.textContent=msg;toast.classList.add("show");
  clearTimeout(showToast.t);showToast.t=setTimeout(()=>toast.classList.remove("show"),2400);
}
function runGlobalSearch(){
  const q=$("globalSearch").value.trim();
  examSearch.value=q;categoryFilter.value=levelFilter.value="all";renderExams();
  $("exams").scrollIntoView({behavior:"smooth"});
  if(!q)showToast("Enter an exam or keyword to search.");
}
on(moreBtn,"click",()=>{visibleCount+=PAGE_SIZE;renderExams(false)});
on(examGrid,"click",e=>{const b=e.target.closest("[data-exam]");if(b)openExam(b.dataset.exam)});
[examSearch,categoryFilter,levelFilter].forEach(c=>on(c,"input",()=>renderExams()));
on($("clearFilters"),"click",()=>{examSearch.value="";categoryFilter.value=levelFilter.value="all";renderExams()});
on($("dialogClose"),"click",()=>dialog.close());
on(dialog,"click",e=>{if(e.target===dialog)dialog.close()});
on($("menuToggle"),"click",()=>$("menuToggle").setAttribute("aria-expanded",String($("mainNav").classList.toggle("open"))));
document.querySelectorAll("#mainNav a").forEach(a=>on(a,"click",()=>{$("mainNav").classList.remove("open");$("menuToggle").setAttribute("aria-expanded","false")}));
document.querySelectorAll(".category-card").forEach(c=>on(c,"click",()=>{
  categoryFilter.value=c.dataset.category;examSearch.value="";renderExams();
  $("exams").scrollIntoView({behavior:"smooth"});
}));
on($("globalSearchBtn"),"click",runGlobalSearch);
on($("globalSearch"),"keydown",e=>{if(e.key==="Enter")runGlobalSearch()});
on($("finderForm"),"submit",e=>{
  e.preventDefault();
  const edu=$("educationLevel").value,interest=$("interestArea").value;
  const items=(suggestions[interest]||[]).map(x=>`<li>${esc(x)}</li>`).join("")||"<li>No suggestions for this selection.</li>";
  $("finderResult").innerHTML=`<strong>Starting points for ${esc(edu)} · ${esc(interest)}:</strong><ul>${items}</ul><small>These are exploration ideas, not an eligibility confirmation. Check each exam's current rules.</small>`;
});

/* ---------- Date, time, greeting (IST) ---------- */
function updateNexoraDateTime(){
  const now=new Date(),f=o=>new Intl.DateTimeFormat("en-IN",{timeZone:"Asia/Kolkata",...o}).format(now);
  const h=+f({hour:"2-digit",hourCycle:"h23"});
  setText("currentDay",f({weekday:"long"}));
  setText("currentDate",f({day:"numeric",month:"long",year:"numeric"}));
  setText("currentTime",f({hour:"2-digit",minute:"2-digit",second:"2-digit",hour12:true}));
  setText("greeting",h<12?"Good Morning ☀️":h<17?"Good Afternoon 🌤️":h<21?"Good Evening 🌆":"Good Night 🌙");
}

/* ---------- College directory ---------- */
let activeCollegeCategory="iit";
function showCollegeCategory(cat){
  if(!collegeDirectory[cat])return alert("This college category is not available yet.");
  const res=$("college-results"),title=$("college-results-title");
  if(!res||!title)return alert("College results HTML section not found.");
  activeCollegeCategory=cat;
  title.textContent=collegeCategoryNames[cat]||cat;
  res.style.display="block";
  renderCollegeResults();
  res.scrollIntoView({behavior:"smooth",block:"start"});
}
function renderCollegeResults(){
  const list=$("college-list");if(!list)return;
  const kw=($("college-search")?.value||"").toLowerCase().trim();
  const found=(collegeDirectory[activeCollegeCategory]||[]).filter(c=>[c.name,c.city,c.state].some(v=>v.toLowerCase().includes(kw)));
  list.innerHTML=found.length?found.map(c=>`
    <div class="college-card"><div class="college-card-content">
      <h3>${esc(c.name)}</h3><p>${esc(c.city)}, ${esc(c.state)}</p><p>Established: ${esc(c.year||"See official website")}</p>
      <span class="college-tier">${esc(c.tier)}</span>
      <button data-college="${esc(c.code)}">View Complete Profile</button>
    </div></div>`).join(""):"<p>No college found. Try another search.</p>";
}
const info=(l,v)=>`<div class="iit-info-card"><small>${l}</small><strong>${v}</strong></div>`;
const sec=(h,b)=>`<section class="iit-profile-section"><h3>${h}</h3>${b}</section>`;
function openIITProfile(code){
  const c=(collegeDirectory[activeCollegeCategory]||[]).find(x=>x.code===code);
  if(!c)return alert("College not found!");
  const ov=$("iitProfileOverlay"),name=$("iitProfileName"),loc=$("iitProfileLocation"),content=$("iitProfileContent");
  if(!ov||!name||!loc||!content)return alert("Profile popup HTML is missing.");
  const meta=collegeMeta[activeCollegeCategory]||collegeMeta.engineering;
  name.textContent=c.name;loc.textContent=`${c.city}, ${c.state}`;
  content.innerHTML=
    sec("College Overview",`<div class="iit-info-grid">${info("Institution founding year",esc(c.year||"Check official website"))}${info("Location",esc(c.city)+", "+esc(c.state))}${info("Institution type",esc(c.type||meta.type))}${info("NexoraPath tier",esc(c.tier))}</div>`)+
    sec("Courses and Programmes",`<div class="iit-course-list">${(c.courses||[]).map(x=>`<div class="iit-course-item">${esc(x)}</div>`).join("")}</div>`)+
    sec("Course Duration",`<div class="iit-info-grid">${meta.duration.map(d=>info(esc(d[0]),esc(d[1]))).join("")}</div>`)+
    sec("Admission Process",`<p>${esc(meta.admission)}</p>`)+
    sec("Fees and Scholarships","<p>Fees depend on the institute, course, category and academic year. Check the official institute website for current fees and scholarship details.</p>")+
    sec("Official Website",`<a href="${esc(c.website)}" target="_blank" rel="noopener">Visit Official Website ↗</a>`);
  ov.style.display="flex";document.body.style.overflow="hidden";
}
function closeIITProfile(){
  const ov=$("iitProfileOverlay");if(ov)ov.style.display="none";
  document.body.style.overflow="";
}
on($("college-list"),"click",e=>{const b=e.target.closest("[data-college]");if(b)openIITProfile(b.dataset.college)});
on($("iitProfileOverlay"),"click",e=>{if(e.target.id==="iitProfileOverlay")closeIITProfile()});
on(document,"keydown",e=>{if(e.key==="Escape")closeIITProfile()});
on($("college-search"),"input",renderCollegeResults);

setText("year",new Date().getFullYear());
renderExams();
updateNexoraDateTime();
setInterval(updateNexoraDateTime,1000);
